import React, { useState } from "react";

function InputForm({ setPredictionData, setRecommendations }) {
  const [childName, setChildName] = useState("");
  const [screenTime, setScreenTime] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://127.0.0.1:8000/predict", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          child_name: childName,
          daily_screen_time: parseFloat(screenTime),
        }),
      });

      const data = await response.json();
      setPredictionData(data);
      setRecommendations(data.recommendations || []);
    } catch (err) {
      alert("Error fetching prediction: " + err.message);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={styles.form}>
      <div style={styles.inputGroup}>
        <label style={styles.label}>Child Name</label>
        <input
          type="text"
          value={childName}
          onChange={(e) => setChildName(e.target.value)}
          placeholder="Enter child's name"
          style={styles.input}
          required
        />
      </div>

      <div style={styles.inputGroup}>
        <label style={styles.label}>Daily Screen Time (hours)</label>
        <input
          type="number"
          value={screenTime}
          onChange={(e) => setScreenTime(e.target.value)}
          placeholder="e.g., 3.5"
          style={styles.input}
          required
        />
      </div>

      <button type="submit" style={styles.button}>
        Predict
      </button>
    </form>
  );
}

const styles = {
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "20px",
    padding: "20px",
    backgroundColor: "#f8fafc",
    borderRadius: "12px",
    boxShadow: "0px 4px 12px rgba(0,0,0,0.08)",
  },

  inputGroup: {
    display: "flex",
    flexDirection: "column",
    gap: "6px",
  },

  label: {
    fontSize: "14px",
    fontWeight: "600",
    color: "#1e293b",
  },

  input: {
    padding: "12px",
    borderRadius: "8px",
    border: "1px solid #cbd5e1",
    outline: "none",
    fontSize: "15px",
    transition: "0.3s",
  },

  button: {
    backgroundColor: "#2563eb",
    color: "white",
    padding: "14px",
    borderRadius: "10px",
    border: "none",
    fontSize: "16px",
    cursor: "pointer",
    transition: "0.3s",
  },
};

export default InputForm;
